package dao.admin;
import config.DatabaseConnection;import java.sql.*;import java.util.*;
public final class AdminDAO{
 public Result find(String module,String keyword){if("Báo cáo".equals(module)){return findReport();}String q=keyword==null?"":keyword.trim();String sql;String[] cols;
  switch(module){
   case "Phân quyền" -> {cols=new String[]{"Mã vai trò","Vai trò","Trạng thái","Quyền được cấp"};sql="SELECT v.MaVaiTro,v.TenVaiTro,v.TrangThai,COALESCE(STUFF((SELECT N', '+q2.TenQuyen FROM dbo.VaiTroQuyen vq2 JOIN dbo.Quyen q2 ON q2.MaQuyen=vq2.MaQuyen WHERE vq2.MaVaiTro=v.MaVaiTro FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,2,N''),N'Chưa cấp quyền') FROM dbo.VaiTro v WHERE (?='' OR v.MaVaiTro LIKE ? OR v.TenVaiTro LIKE ?) ORDER BY v.TenVaiTro";}
   case "Thiết bị" -> {cols=new String[]{"Mã thiết bị","Tên thiết bị","Loại","Model","Serial","Vị trí","Tình trạng"};sql="SELECT t.MaThietBi,t.TenThietBi,COALESCE(l.TenLoaiThietBi,N''),t.Model,t.SoSerial,t.ViTri,t.TinhTrang FROM dbo.ThietBi t LEFT JOIN dbo.LoaiThietBi l ON l.MaLoaiThietBi=t.MaLoaiThietBi WHERE (?='' OR t.MaThietBi LIKE ? OR t.TenThietBi LIKE ? OR t.SoSerial LIKE ?) ORDER BY t.TenThietBi";}
   case "Đánh giá nhân viên" -> {cols=new String[]{"Mã đánh giá","Nhân viên","Kỳ đánh giá","Ngày đánh giá","Điểm","Người đánh giá","Nhận xét"};sql="SELECT d.MaDanhGia,n.HoTen,d.KyDanhGia,d.NgayDanhGia,d.Diem,e.HoTen,d.NhanXet FROM dbo.DanhGiaNhanVien d JOIN dbo.NhanVien n ON n.MaNhanVien=d.MaNhanVien JOIN dbo.NhanVien e ON e.MaNhanVien=d.NguoiDanhGia WHERE (?='' OR n.HoTen LIKE ? OR n.MaNhanVien LIKE ? OR d.KyDanhGia LIKE ?) ORDER BY d.NgayDanhGia DESC";}
   case "Cấu hình hệ thống" -> {cols=new String[]{"Mã cấu hình","Giá trị","Kiểu dữ liệu","Mô tả","Cập nhật lúc","Cập nhật bởi"};sql="SELECT c.MaCauHinh,c.GiaTri,c.KieuDuLieu,c.MoTa,c.CapNhatLuc,COALESCE(a.TenDangNhap,N'') FROM dbo.CauHinhHeThong c LEFT JOIN dbo.TaiKhoan a ON a.MaTaiKhoan=c.CapNhatBoi WHERE (?='' OR c.MaCauHinh LIKE ? OR c.MoTa LIKE ?) ORDER BY c.MaCauHinh";}
   case "Nhật ký hệ thống" -> {cols=new String[]{"Mã nhật ký","Thời điểm","Tài khoản","Hành động","Đối tượng","Mã đối tượng","Nội dung"};sql="SELECT TOP(500) n.MaNhatKy,n.ThoiDiem,COALESCE(a.TenDangNhap,N''),n.HanhDong,n.DoiTuong,n.MaDoiTuong,n.NoiDung FROM dbo.NhatKyHeThong n LEFT JOIN dbo.TaiKhoan a ON a.MaTaiKhoan=n.MaTaiKhoan WHERE (?='' OR n.HanhDong LIKE ? OR n.DoiTuong LIKE ? OR n.NoiDung LIKE ?) ORDER BY n.ThoiDiem DESC";}
   case "Thông báo" -> {cols=new String[]{"Mã thông báo","Tiêu đề","Loại","Thời gian gửi","Trạng thái","Kênh gửi","Người nhận"};sql="SELECT t.MaThongBao,t.TieuDe,t.LoaiThongBao,t.ThoiGianGui,t.TrangThai,t.KenhGui,COALESCE(n.HoTen,N'Chung') FROM dbo.ThongBao t LEFT JOIN dbo.NhanVien n ON n.MaNhanVien=t.MaNhanVien WHERE (?='' OR t.TieuDe LIKE ? OR t.NoiDung LIKE ?) ORDER BY t.ThoiGianGui DESC";}
   default -> {cols=new String[]{"Chỉ số","Giá trị","Ghi chú"};sql="SELECT N'Tổng nhân viên',CONVERT(nvarchar(30),COUNT(*)),N'Nhân sự' FROM dbo.NhanVien UNION ALL SELECT N'Tổng bác sĩ',CONVERT(nvarchar(30),COUNT(*)),N'Chuyên môn' FROM dbo.BacSi UNION ALL SELECT N'Lịch hẹn hôm nay',CONVERT(nvarchar(30),COUNT(*)),N'Khám bệnh' FROM dbo.LichHen WHERE CAST(ThoiGianHen AS date)=CAST(SYSDATETIME() AS date) UNION ALL SELECT N'Hóa đơn chưa thanh toán',CONVERT(nvarchar(30),COUNT(*)),N'Tài chính' FROM dbo.HoaDon WHERE TrangThai IN (N'ChuaThanhToan',N'ThanhToanMotPhan') UNION ALL SELECT N'Thuốc cận hạn 30 ngày',CONVERT(nvarchar(30),COUNT(*)),N'Lô còn tồn kho' FROM dbo.LoThuoc WHERE HanSuDung>=CAST(SYSDATETIME() AS date) AND HanSuDung<DATEADD(day,31,CAST(SYSDATETIME() AS date)) AND SoLuongTon>0 UNION ALL SELECT N'Doanh thu hôm nay',CONVERT(nvarchar(30),COALESCE(SUM(SoTien),0)),N'Giao dịch đã thu' FROM dbo.GiaoDichThanhToan WHERE TrangThai=N'ThanhCong' AND CAST(ThoiGianGiaoDich AS date)=CAST(SYSDATETIME() AS date) UNION ALL SELECT N'Bệnh nhân vắng hôm nay',CONVERT(nvarchar(30),COUNT(*)),N'Lịch hẹn' FROM dbo.LichHen WHERE TrangThai=N'VangMat' AND CAST(ThoiGianHen AS date)=CAST(SYSDATETIME() AS date) UNION ALL SELECT TOP(10) N'Bác sĩ hủy nhiều lịch: '+COALESCE(n.HoTen,N'Chưa phân công'),CONVERT(nvarchar(30),COUNT(*)),N'Lịch đã hủy' FROM dbo.LichHen h LEFT JOIN dbo.NhanVien n ON n.MaNhanVien=h.MaNhanVien WHERE h.TrangThai=N'DaHuy' GROUP BY n.HoTen ORDER BY COUNT(*) DESC";}
  }
  List<Object[]> rows=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){boolean report=module.equals("Báo cáo");if(!report){s.setString(1,q);s.setString(2,"%"+q+"%");s.setString(3,"%"+q+"%");if(module.equals("Thiết bị")||module.equals("Đánh giá nhân viên")||module.equals("Nhật ký hệ thống")){s.setString(4,"%"+q+"%");}}try(ResultSet r=s.executeQuery()){while(r.next()){Object[] row=new Object[cols.length];for(int i=0;i<cols.length;i++)row[i]=r.getObject(i+1);rows.add(row);}}return new Result(cols,List.copyOf(rows));}catch(SQLException e){throw new AdminDAOException("Không thể tải dữ liệu quản trị. Chi tiết hệ thống: "+e.getMessage(),e);}
 }
 private Result findReport(){String[] cols={"Chỉ số","Giá trị","Ghi chú"};String sql="SELECT N'Tổng nhân viên',CONVERT(nvarchar(30),COUNT(*)),N'Nhân sự' FROM dbo.NhanVien UNION ALL SELECT N'Tổng bác sĩ',CONVERT(nvarchar(30),COUNT(*)),N'Chuyên môn' FROM dbo.BacSi UNION ALL SELECT N'Lịch hẹn hôm nay',CONVERT(nvarchar(30),COUNT(*)),N'Khám bệnh' FROM dbo.LichHen WHERE CAST(ThoiGianHen AS date)=CAST(SYSDATETIME() AS date) UNION ALL SELECT N'Hóa đơn chưa thanh toán',CONVERT(nvarchar(30),COUNT(*)),N'Tài chính' FROM dbo.HoaDon WHERE TrangThai IN (N'ChuaThanhToan',N'ThanhToanMotPhan') UNION ALL SELECT N'Thuốc cận hạn 30 ngày',CONVERT(nvarchar(30),COUNT(*)),N'Lô còn tồn kho' FROM dbo.LoThuoc WHERE HanSuDung>=CAST(SYSDATETIME() AS date) AND HanSuDung<DATEADD(day,31,CAST(SYSDATETIME() AS date)) AND SoLuongTon>0 UNION ALL SELECT N'Doanh thu hôm nay',CONVERT(nvarchar(30),COALESCE(SUM(SoTien),0)),N'Giao dịch đã thu' FROM dbo.GiaoDichThanhToan WHERE TrangThai=N'ThanhCong' AND CAST(ThoiGianGiaoDich AS date)=CAST(SYSDATETIME() AS date) UNION ALL SELECT N'Bệnh nhân vắng hôm nay',CONVERT(nvarchar(30),COUNT(*)),N'Lịch hẹn' FROM dbo.LichHen WHERE TrangThai=N'VangMat' AND CAST(ThoiGianHen AS date)=CAST(SYSDATETIME() AS date)";List<Object[]> rows=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(sql);ResultSet r=s.executeQuery()){while(r.next())rows.add(new Object[]{r.getObject(1),r.getObject(2),r.getObject(3)});return new Result(cols,List.copyOf(rows));}catch(SQLException e){throw new AdminDAOException("Không thể tải báo cáo. Chi tiết hệ thống: "+e.getMessage(),e);}}
 public List<Object[]> doctorCancellationStats(){String sql="SELECT TOP(10) N'Bác sĩ hủy lịch: '+COALESCE(n.HoTen,N'Chưa phân công'),CONVERT(nvarchar(30),COUNT(*)),N'Lịch đã hủy' FROM dbo.LichHen h LEFT JOIN dbo.NhanVien n ON n.MaNhanVien=h.MaNhanVien WHERE h.TrangThai=N'DaHuy' GROUP BY n.HoTen ORDER BY COUNT(*) DESC";List<Object[]> rows=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(sql);ResultSet r=s.executeQuery()){while(r.next())rows.add(new Object[]{r.getObject(1),r.getObject(2),r.getObject(3)});return List.copyOf(rows);}catch(SQLException e){throw new AdminDAOException("Không thể tải thống kê bác sĩ hủy lịch. Chi tiết hệ thống: "+e.getMessage(),e);}}
 public record Result(String[] columns,List<Object[]> rows){ }
}
